async function bookmark(){const vault=store.vault,anchor=selectedAnchor();if(!vault||!anchor)return;try{await vault.commit(crypto.randomUUID(),'note',crypto.randomUUID(),0,{anchor,text:'',quote:window.getSelection()?.toString()||'',createdAt:new Date().toISOString()});noteSaved.value=true;actions.value=false}catch(e){error.value=(e as Error).message}}
async function writeNote(){const vault=store.vault,anchor=noteAnchor.value;if(!vault||!anchor||noteBusy.value)return;noteBusy.value=true;try{await vault.commit(crypto.randomUUID(),'note',crypto.randomUUID(),0,{anchor,text:noteText.value,quote:noteQuote.value,createdAt:new Date().toISOString()});noteSaved.value=true;noteOpen.value=false}catch(e){error.value=(e as Error).message}finally{noteBusy.value=false}}
onMounted(async()=>{document.addEventListener('selectionchange',positionSelection);window.addEventListener('scroll',positionSelection,{passive:true});window.addEventListener('resize',positionSelection);window.visualViewport?.addEventListener('resize',positionSelection);window.addEventListener('reader-private-commit',reflectArchive);updateVoices();if('speechSynthesis' in window)speechSynthesis.addEventListener('voiceschanged',updateVoices);document.addEventListener('visibilitychange',stopHiddenSpeech);window.addEventListener('reader-local-locked',lockedSpeech);try{const vault=store.vault;if(!vault)return;const current=()=>!disposed&&!lineDeleted&&store.vault===vault&&vault.unlocked;const savedPreferences=await vault.read<Record<string,unknown>>('settings:reading');if(!current())return;preferences.value=readingPreferences(savedPreferences?.value);fontSize.value=preferences.value.fontSize;preferenceRevision.value=savedPreferences?.revision||0;preferenceExtra.value=savedPreferences?.value||{};document.documentElement.dataset.theme=preferences.value.theme;pinnedRevision.value=requestedLineRevision(route.query.revision);const [loaded,branchRows,primary]=await Promise.all([readingLine(vault,storyId,branchId,pinnedRevision.value),vault.list<LocalBranch>('branch'),vault.read<MainReadingLine>(mainLineKey(storyId))]);if(!current())return;lineArchived.value=!!loaded.branchHead?.value.archived;branchEntries.value=branchRows.filter(r=>r.value.storyId===storyId);primaryBranch.value=primary?.value.branchId||null;story.value=loaded.line;displayedRevision.value=loaded.branch?.revision||loaded.story.revision;mediaSource.value=loaded.branch||loaded.story;lineName.value=loaded.branch?.value.name||'原文';if(!story.value||story.value.kind!=='story'){story.value=null;throw new Error('找不到这本故事')};const progress=await vault.read<ProgressAnchor>(progressId.value);if(!current())return;progressRevision=progress?.revision||0;const explicit=typeof route.query.paragraph==='string'?route.query.paragraph:null;let anchor=progress?.value,anchorError='';if(explicit){const para=await vault.read<Paragraph>(explicit);if(!current())return;if(para&&story.value.value.paragraphIds.includes(explicit))anchor={storyId,branchId,paragraphId:explicit,offset:unicodeOffset(para.value.text,Number(route.query.offset)||0)};else anchorError='这个位置已失效，原记录仍保留'}const index=anchor?story.value.value.chapters.findIndex(c=>c.paragraphIds.includes(anchor!.paragraphId)):0;await loadChapter(Math.max(0,index),anchor);if(!current())return;if(anchorError)error.value=anchorError;else if(typeof route.query.task==='string'){const task=await vault.read<import('../writing/contract').WritingRun>(route.query.task);if(!current())return;if(task?.kind==='settings'&&task.value.assetType==='writing-run'&&task.value.storyId===storyId&&task.value.parentBranchId===branchId&&!task.value.purpose){writingAnchor.value=task.value.anchor;writingOpen.value=true}else error.value='这份写作记录不属于当前故事线，原记录保留'}else if(route.query.write==='1')fromHere()}catch(e){if(!disposed){error.value=(e as Error).message;busy.value=false}}})
function saveBeforeLeaving(){if(timer)clearTimeout(timer);void save()}
onBeforeRouteLeave(async()=>{if(timer)clearTimeout(timer);await save()})
onBeforeRouteUpdate(async()=>{if(timer)clearTimeout(timer);await save()})
window.addEventListener('pagehide',saveBeforeLeaving)
onUnmounted(()=>{archiveEpoch++;cancelAnimationFrame(selectionFrame);document.removeEventListener('selectionchange',positionSelection);window.removeEventListener('scroll',positionSelection);window.removeEventListener('resize',positionSelection);window.visualViewport?.removeEventListener('resize',positionSelection);window.removeEventListener('reader-private-commit',reflectArchive);mediaLifecycle.abort();speech.stop();window.removeEventListener('reader-local-locked',lockedSpeech);document.removeEventListener('visibilitychange',stopHiddenSpeech);if('speechSynthesis' in window)speechSynthesis.removeEventListener('voiceschanged',updateVoices);saveBeforeLeaving();disposed=true;searchController?.abort();observer?.disconnect();window.removeEventListener('pagehide',saveBeforeLeaving)})
const {activityError,retryActivity}=useLocalReadingActivity(()=>{const source=mediaSource.value;return {vault:store.vault,storyId,source:source&&(source.kind==='story'||source.kind==='branch')?{id:source.id,kind:source.kind,revision:source.revision}:null,anchor:currentAnchor.value?{paragraphId:currentAnchor.value.paragraphId,offset:currentAnchor.value.offset}:null,enabled:!disposed&&!lineDeleted&&!busy.value&&paragraphs.value.length>0&&!drawer.value&&!actions.value&&!preferencesOpen.value&&!searchOpen.value&&!noteOpen.value&&!writingOpen.value&&!editOpen.value&&!historyOpen.value&&!peopleOpen.value&&!speechOpen.value}})
</script>
<template><ReaderShell v-model:controls="readerControls" :label="story?.value.title||'故事'" :style="{background:preferences.theme==='dark'?'var(--paper)':readingPaper[preferences.paper]}"><template #header><header class="final-reader-header"><RouterLink to="/local/library" class="final-icon-button" aria-label="返回书架"><ArrowLeft :size="22"/></RouterLink><div class="final-reader-heading"><strong>{{story?.value.title||'故事'}}</strong><small>{{lineName}} · {{historical?'历史 v'+pinnedRevision:saved?'位置已保存':'本地阅读'}}</small></div><div class="final-page-actions"><RouterLink v-if="!historical" :to="{path:'/local/stage/'+storyId,query:{branch:branchId||undefined}}" class="final-icon-button" aria-label="进入故事演出"><Clapperboard :size="20"/></RouterLink><button class="final-icon-button" aria-label="更多阅读操作" @click="openActions"><MoreHorizontal :size="20"/></button></div></header></template><div v-if="error" class="final-error final-reader-alert" role="alert"><span>{{error}}</span><button class="final-icon-button" aria-label="关闭提示" @click="error=''">×</button></div><p v-if="activityError" class="final-error final-reader-alert" role="status">{{activityError}}<button @click="retryActivity">重试保存</button></p><p v-if="noteSaved" class="final-subtle" role="status">已保存到阅读笔记</p><ReaderPages ref="pagingRef" :mode="preferences.pagingMode" :double-page="preferences.doublePage" :line-width="preferences.lineWidth" :layout-key="pagingLayout" :content-key="storyId+':'+branchId+':'+chapterIndex+':'+pageStart" :anchor="currentAnchor" :busy="busy" :has-previous="chapterIndex>0||pageStart>0" :has-next="!!story&&(chapterIndex<story.value.chapters.length-1||pageStart+paragraphs.length<(story.value.chapters[chapterIndex]?.paragraphIds.length||0))" @anchor="pageAnchor" @boundary="pageBoundary"><article class="final-reader-body" :aria-busy="busy" :style="readerStyle"><h1 v-if="!inlineChapterTitle">{{story?.value.chapters[chapterIndex]?.title}}</h1><p v-if="busy" role="status">正在打开正文…</p><template v-for="(paragraph,index) in paragraphs" :key="paragraph.id"><AssetLinks v-if="mediaSource" :target-id="mediaSource.id" :target-kind="mediaSource.kind" :target-revision="mediaSource.revision" :paragraph-id="paragraph.id" role="illustration-before"/><component :is="inlineChapterTitle&&index===0?'h1':'p'" :id="paragraph.id" class="final-reader-paragraph">{{paragraph.value.text}}</component><AssetLinks v-if="mediaSource" :target-id="mediaSource.id" :target-kind="mediaSource.kind" :target-revision="mediaSource.revision" :paragraph-id="paragraph.id" role="illustration-after"/></template><button v-if="!paged&&story&&pageStart+paragraphs.length<(story.value.chapters[chapterIndex]?.paragraphIds.length||0)" :disabled="moreBusy" @click="more">继续阅读本章</button><CharactersPanel v-if="story&&!historical" :story-id="storyId" :branch-id="branchId" :anchor="peopleAnchor" :open="peopleOpen" @close="peopleOpen=false"/><EditPanel v-if="story" :story-id="storyId" :branch-id="branchId" :selection="editSelection" :source-revision="pinnedRevision" :read-only="lineArchived" :open="editOpen" @close="editOpen=false"/><WritingPanel v-if="story&&(!historical||historicalComposeStarted)" :story-id="storyId" :branch-id="branchId" :anchor="writingAnchor" :source-revision="pinnedRevision" :read-only="lineArchived" :open="writingOpen" @close="writingOpen=false"/><div v-if="!paged" class="final-reader-bottom"><button :disabled="chapterIndex===0||busy" @click="loadChapter(chapterIndex-1)"><ChevronLeft :size="17"/>上一章</button><button :disabled="!story||chapterIndex>=story.value.chapters.length-1||busy" @click="loadChapter(chapterIndex+1)">下一章<ChevronRight :size="17"/></button></div></article></ReaderPages><template #controls><button aria-label="打开目录" @click="drawer=true"><List :size="18"/>目录</button><button aria-label="打开听书" @click="speechOpen=true;updateVoices()"><Headphones :size="18"/>听</button><button aria-label="切换夜间阅读" :aria-pressed="preferences.theme==='dark'" :disabled="preferenceBusy" @click="toggleNight"><Moon :size="18"/>夜间</button><button aria-label="打开阅读设置" @click="showPreferences"><SlidersHorizontal :size="18"/>设置</button></template><template #selection><div v-if="selectionTools" class="reader-selection-tools" :style="{left:selectionTools.x+'px',top:selectionTools.y+'px'}" role="toolbar" aria-label="选中文字操作"><button :disabled="lineArchived" @pointerdown.prevent @click="fromHere"><Sparkles :size="16"/>从这里写</button><button @pointerdown.prevent @click="startNote"><NotebookPen :size="16"/>笔记</button><button @pointerdown.prevent @click="copySelection"><Copy :size="16"/>复制</button><button aria-label="更多选区操作" @pointerdown.prevent @click="openActions"><MoreHorizontal :size="18"/></button></div></template><HistoryPanel v-if="historyOpen" :story-id="storyId" :branch-id="branchId" @close="historyOpen=false" @continue="continueHistoryAt"/><Sheet v-if="actions" title="阅读操作" @close="actions=false"><div class="final-chapter-list"><button :disabled="lineArchived" @click="fromHere"><Sparkles :size="20"/>从这里写</button><RouterLink class="final-text-link" :to="{path:'/local/lines/'+storyId,query:{branch:branchId||undefined}}"><GitBranch :size="20"/>故事线</RouterLink><button v-if="!historical" @click="openPeople"><Users :size="20"/>故事人物</button><button @click="actions=false;speechOpen=true;updateVoices()">系统听书</button><button v-if="!historical" @click="mediaEntry()">为这段配图</button><button v-if="!historical" @click="indexEntry">保存到内容索引</button><button v-if="!historical" @click="videoEntry">让这段动起来</button><button v-if="!historical" @click="mediaEntry('tts','speech')">在线配音</button><button v-if="mediaSource&&!historical" @click="mediaEntry('image','cover')">制作封面</button><button @click="actions=false;historyOpen=true">历史版本</button><RouterLink v-if="historical" class="final-text-link" :to="{path:'/local/read/'+storyId,query:{branch:branchId||undefined}}">返回当前版本</RouterLink><button @click="exportOriginal"><Download :size="20"/>导出原文件</button><button @click="bookmark"><Bookmark :size="20"/>保存书签</button><button :disabled="lineArchived" @click="openEditor()">{{historical?'从旧版修订':'编辑正文'}}</button><button @click="openEditor(true)">编辑记录</button><button @click="startNote"><NotebookPen :size="20"/>写笔记</button><RouterLink class="final-text-link" :to="{path:'/local/notebook',query:{story:storyId}}">本书笔记</RouterLink><button @click="actions=false;searchOpen=true"><Search :size="20"/>搜索正文</button><button @click="showPreferences"><SlidersHorizontal :size="20"/>阅读设置</button></div></Sheet><Sheet v-if="drawer" title="目录" @close="drawer=false"><nav v-if="branchEntries.length" class="final-directory-lines" aria-label="目录故事线入口"><RouterLink :to="'/local/read/'+storyId" :aria-current="!branchId?'page':undefined">原文<span v-if="!primaryBranch"> · 主要</span></RouterLink><RouterLink v-for="entry in branchEntries" :key="entry.id" :to="{path:'/local/read/'+storyId,query:{branch:entry.id}}" :aria-current="branchId===entry.id?'page':undefined">{{entry.value.name}}<span v-if="primaryBranch===entry.id"> · 主要</span><span v-if="entry.value.archived"> · 已归档</span></RouterLink></nav><ChapterDirectory :chapters="story?.value.chapters||[]" :active="chapterIndex" @select="loadChapter"/></Sheet><Sheet v-if="searchOpen" title="搜索正文" @close="searchController?.abort();searchOpen=false"><div class="final-reader-tools"><form @submit.prevent="find"><label>关键词<input v-model="searchQuery" type="search" maxlength="500" placeholder="输入原文关键词"></label><div class="final-page-actions"><button :disabled="searching||!searchQuery">搜索</button><button v-if="searching" type="button" @click="searchController?.abort()">停止</button></div></form><p v-if="searching" role="status">正在查找 · {{Math.round(searchProgress*100)}}%</p><p v-else-if="searchTotal" class="final-subtle">{{searchTotal}} 处<span v-if="searchTotal>200">，显示前 200 处</span></p><button v-for="(hit,index) in searchHits" :key="index" class="final-search-hit" @click="jump(hit.anchor)"><small>{{hit.chapter}}</small><span>{{hit.excerpt}}</span></button></div></Sheet><Sheet v-if="noteOpen" title="写笔记" @close="!noteBusy&&(noteOpen=false)"><form class="final-reader-tools" @submit.prevent="writeNote"><blockquote v-if="noteQuote">{{noteQuote}}</blockquote><label>想法<textarea v-model="noteText" maxlength="1000000" rows="6"/></label><button class="primary" :disabled="noteBusy">保存笔记</button></form></Sheet><Sheet v-if="speechOpen" title="系统听书" @close="speechOpen=false"><div class="final-reader-tools"><label>音色<select v-model="speechVoice"><option value="">系统默认</option><option v-for="voice in voices" :key="voice.voiceURI" :value="voice.voiceURI">{{voice.name}} · {{voice.lang}}{{voice.localService?' · 设备音色':''}}</option></select></label><label>速度<input v-model.number="speechRate" type="range" min="0.5" max="2" step="0.1"></label><label>定时停止<select v-model.number="speechMinutes"><option :value="0">不定时</option><option :value="5">5 分钟</option><option :value="15">15 分钟</option><option :value="30">30 分钟</option></select></label><p role="status">{{{idle:'已停止',waiting:'等待系统语音',speaking:'正在朗读',paused:'已暂停',finished:'已读完'}[speechState]}}</p><div class="final-grid-actions"><button v-if="speechState==='idle'||speechState==='finished'" @click="startSpeech">从这里听</button><button v-else-if="speechState==='paused'" @click="speech.resume()">继续</button><button v-else @click="speech.pause()">暂停</button><button @click="speech.stop()">停止</button></div></div></Sheet><Sheet v-if="preferencesOpen" title="阅读设置" @close="!preferenceBusy&&(preferencesOpen=false)"><form class="final-reader-tools" @submit.prevent="savePreferences"><label>翻页<select aria-label="翻页模式" v-model="preferences.pagingMode"><option value="scroll">滚动</option><option value="curl">仿真卷页</option><option value="cover">覆盖</option><option value="slide">平移</option><option value="none">无动画</option></select></label><label class="reader-double-setting"><input v-model="preferences.doublePage" type="checkbox">宽屏双页</label><label>主题<select aria-label="主题" v-model="preferences.theme"><option value="light">日间</option><option value="dark">夜读</option></select></label><label>纸色<select aria-label="纸色" v-model="preferences.paper"><option value="theme">跟随界面</option><option value="warm">暖纸</option><option value="white">白纸</option><option value="cream">奶油</option><option value="green">青竹</option><option value="rose">浅玫瑰</option></select></label><label>字体<select aria-label="字体" v-model="preferences.font"><option value="serif">宋体</option><option value="sans">黑体</option><option value="system">系统字体</option></select></label><label>字号 · {{fontSize}}<input v-model.number="fontSize" type="range" min="14" max="36"></label><label>行距<input v-model.number="preferences.lineHeight" type="range" min="1.3" max="2.8" step="0.05"></label><label>段距<input v-model.number="preferences.paragraphGap" type="range" min="0.5" max="3" step="0.1"></label><label>行宽<input v-model.number="preferences.lineWidth" type="range" min="400" max="1100" step="10"></label><button class="primary" :disabled="preferenceBusy">保存设置</button></form></Sheet></ReaderShell></template>

<style scoped>
.reader-double-setting{display:flex!important;align-items:center;gap:12px}.reader-double-setting input{width:20px!important;min-height:20px!important}.final-directory-lines{display:flex;gap:10px;flex-wrap:wrap;border-bottom:1px solid var(--edge);padding-bottom:18px;margin-bottom:18px}.final-directory-lines a{padding:10px 12px;border:1px solid var(--edge);border-radius:12px;font-size:13px;overflow-wrap:anywhere}.final-directory-lines a[aria-current=page]{background:var(--wash);border-color:var(--accent);color:var(--accent)}.final-directory-lines span{font-size:11px;color:var(--quiet)}

.final-reader-body{padding-bottom:100px}.reader-selection-tools{position:fixed;z-index:35;display:flex;gap:2px;padding:4px;width:min(344px,calc(100vw - 24px));max-width:calc(100vw - 24px);box-sizing:border-box;border:1px solid var(--edge);border-radius:12px;background:var(--canvas);box-shadow:0 4px 24px color-mix(in srgb,var(--ink) 12%,transparent)}.reader-selection-tools button{display:flex;gap:5px;align-items:center;justify-content:center;min-height:44px;min-width:44px;font-size:13px;white-space:nowrap;padding:8px;border:0;background:transparent}
</style>
